/* Nomulous: eponymous signs, tests, triads and syndromes. [name, kind, what you see or do, what it means, history].
   kind: sign | test | triad | syndrome. Written in our own words; history kept to one line. */
window.NOMULOUS = [
  ["Murphy’s sign", "sign", "Press under the right ribs and ask for a deep breath: the patient stops breathing in sharply, mid-breath.", "Acute cholecystitis", "John Benjamin Murphy, a Chicago surgeon, around 1903. He also invented the ‘Murphy button’ for joining bowel."],
  ["McBurney’s point", "sign", "Maximal tenderness one third of the way from the right hip bone (ASIS) to the umbilicus.", "Appendicitis", "Charles McBurney, a New York surgeon, described it in 1889."],
  ["Rovsing’s sign", "sign", "Pressing on the left lower abdomen causes pain in the right lower abdomen.", "Appendicitis", "Thorkild Rovsing, a Danish surgeon, in 1907."],
  ["Blumberg’s sign", "sign", "Pain is worse when your hand is suddenly released from the abdomen than when it presses down (rebound tenderness).", "Peritonitis", "Jacob Moritz Blumberg, a German surgeon and gynaecologist, in 1907."],
  ["Carnett’s sign", "sign", "Abdominal tenderness stays the same or gets worse when the patient tenses their abdominal muscles.", "Pain coming from the abdominal wall, not inside the abdomen", "John Berton Carnett, an American surgeon, in 1926. A cheap test that saves many scans."],
  ["Cullen’s sign", "sign", "Bruising around the umbilicus.", "Bleeding behind the peritoneum, e.g. severe pancreatitis or a ruptured ectopic pregnancy", "Thomas Cullen, a gynaecologist at Johns Hopkins, described it in a ruptured ectopic pregnancy in 1918."],
  ["Grey Turner’s sign", "sign", "Bruising of the flanks.", "Bleeding behind the peritoneum, classically haemorrhagic pancreatitis", "George Grey Turner, an English surgeon, in 1920."],
  ["Kehr’s sign", "sign", "Pain at the tip of the left shoulder in someone with abdominal trauma.", "Blood irritating the diaphragm, classically a ruptured spleen", "Hans Kehr, a German gallbladder surgeon, around the start of the 1900s. The pain is referred along the phrenic nerve (C3 to C5)."],
  ["Courvoisier’s law", "sign", "Painless jaundice with a palpable, enlarged gallbladder.", "Probably not gallstones: think cancer of the pancreatic head", "Ludwig Georg Courvoisier, a Swiss surgeon, in 1890. Stone-scarred gallbladders rarely stretch."],
  ["Sister Mary Joseph nodule", "sign", "A firm lump in the umbilicus.", "A metastasis from abdominal or pelvic cancer", "Named for Sister Mary Joseph Dempsey, surgical assistant to William Mayo, who noticed it while prepping patients. One of very few signs named after a nurse."],
  ["Virchow’s node", "sign", "An enlarged lymph node above the left clavicle (Troisier’s sign).", "Abdominal cancer, classically stomach", "Rudolf Virchow, the German ‘father of pathology’, in 1848. The thoracic duct drains into the left neck."],
  ["Thompson test", "test", "Squeeze the calf of a patient lying face down: the foot doesn’t point down.", "Achilles tendon rupture", "Franklin Simmonds described it in 1957, Thompson and Doherty in 1962. Also called the Simmonds–Thompson test."],
  ["McMurray test", "test", "Flex the knee fully, rotate the shin and straighten it: a painful click along the joint line.", "Meniscal tear", "Thomas Porter McMurray, an orthopaedic surgeon in Liverpool, in 1942."],
  ["Lachman test", "test", "With the knee bent about 20 to 30 degrees, the shin slides too far forward on the thigh, with a soft end point.", "Anterior cruciate ligament (ACL) tear", "Named by Joseph Torg in 1976 after his teacher, John Lachman, in Philadelphia."],
  ["Phalen’s test", "test", "Holding both wrists fully bent for 60 seconds brings on tingling in the thumb, index and middle fingers.", "Carpal tunnel syndrome", "George Phalen, a Cleveland hand surgeon, in the 1950s."],
  ["Tinel’s sign", "sign", "Tapping over a nerve sends tingling into the area it supplies.", "An irritated or regenerating nerve, e.g. carpal tunnel", "Jules Tinel, a French neurologist, in 1915, studying nerve injuries from World War I. Paul Hoffmann described it the same year."],
  ["Finkelstein test", "test", "Thumb tucked into a fist, then the wrist bent towards the little finger: sharp pain at the thumb side of the wrist.", "De Quervain tenosynovitis", "Harry Finkelstein, a New York surgeon, in 1930."],
  ["Froment’s sign", "sign", "Gripping paper between thumb and index finger, the thumb tip bends to compensate.", "Ulnar nerve weakness (weak adductor pollicis)", "Jules Froment, a French neurologist, in 1915."],
  ["Allen’s test", "test", "Compress both wrist arteries, release one, and watch how fast the pale hand flushes pink.", "Whether the hand’s blood supply works through each artery, e.g. before a radial line", "Edgar Van Nuys Allen at the Mayo Clinic, in 1929."],
  ["Trendelenburg sign", "sign", "Standing on one leg, the pelvis drops on the other side.", "Weak hip abductors (gluteus medius) on the standing side", "Friedrich Trendelenburg, a German surgeon, in 1895. He has a position named after him too."],
  ["Steinberg sign", "sign", "With the thumb folded into a closed fist, the tip pokes out past the edge of the palm.", "Marfan syndrome (long thumbs, lax joints)", "Israel Steinberg, an American radiologist, in 1966. Also called the thumb sign."],
  ["Walker–Murdoch sign", "sign", "Wrapping the thumb and little finger around the other wrist, they overlap.", "Marfan syndrome (long fingers, thin wrists)", "Arthur Walker and John Murdoch described the wrist sign in 1955."],
  ["Trousseau’s sign", "sign", "Inflating a blood pressure cuff on the arm makes the hand spasm, with the wrist and fingers bent.", "Low calcium", "Armand Trousseau, a French physician, in the 1860s. He also described clots linked to cancer."],
  ["Chvostek’s sign", "sign", "Tapping in front of the ear makes the corner of the mouth twitch.", "Low calcium (also seen in some healthy people)", "František Chvostek, a Czech-Austrian surgeon, in 1876."],
  ["Kernig’s sign", "sign", "With the hip bent to 90 degrees, straightening the knee is painful and resisted.", "Meningeal irritation, e.g. meningitis", "Vladimir Kernig, a Russian physician, in 1882."],
  ["Brudziński’s sign", "sign", "Bending the neck forward makes the hips and knees bend.", "Meningeal irritation, e.g. meningitis", "Józef Brudziński, a Polish paediatrician, in 1909."],
  ["Babinski sign", "sign", "Stroking the sole makes the big toe go up and the other toes fan out.", "An upper motor neurone lesion (normal in babies)", "Joseph Babinski, a French neurologist, in 1896."],
  ["Hoffmann’s sign", "sign", "Flicking the nail of the middle finger makes the thumb and index finger curl.", "Upper motor neurone lesion, e.g. cervical cord compression", "Johann Hoffmann, a German neurologist, in the late 1800s."],
  ["Romberg’s sign", "sign", "Standing with feet together, the patient is steady with eyes open but sways or falls with eyes closed.", "Loss of position sense (sensory ataxia), not a cerebellar problem", "Moritz Romberg, a German neurologist, in the 1840s, describing tabes dorsalis from syphilis."],
  ["Lhermitte’s sign", "sign", "Bending the neck forward sends an electric shock down the spine and limbs.", "A lesion in the cervical spinal cord, classically multiple sclerosis", "Jean Lhermitte, a French neurologist, in 1924."],
  ["Gowers’ sign", "sign", "A child gets up from the floor by ‘walking’ their hands up their own legs.", "Proximal muscle weakness, classically Duchenne muscular dystrophy", "William Gowers, a London neurologist, in 1879."],
  ["Homans’ sign", "sign", "Calf pain when the ankle is bent upwards.", "Classically DVT, but it is unreliable and no longer recommended", "John Homans, a Boston surgeon, in 1941. He later warned against relying on it himself."],
  ["Battle’s sign", "sign", "Bruising behind the ear, over the mastoid, a day or more after a head injury.", "Fracture of the base of the skull", "William Henry Battle, a London surgeon, in 1890."],
  ["Nikolsky sign", "sign", "Rubbing normal-looking skin makes the top layer slide off.", "Blistering diseases such as pemphigus vulgaris or toxic epidermal necrolysis", "Pyotr Nikolsky, a Russian dermatologist, in 1896."],
  ["Auspitz sign", "sign", "Scraping off a scale leaves tiny pinpoint bleeding spots.", "Psoriasis", "Heinrich Auspitz, an Austrian dermatologist, in the 1800s."],
  ["Koebner phenomenon", "sign", "New skin lesions appear along a scratch or injury.", "Psoriasis, lichen planus or vitiligo", "Heinrich Köbner, a German dermatologist, in 1872."],
  ["Darier’s sign", "sign", "Rubbing a brown skin spot makes it swell, itch and redden.", "Mast cell disease (cutaneous mastocytosis)", "Ferdinand-Jean Darier, a French dermatologist, in the 1800s."],
  ["Janeway lesions", "sign", "Painless red-purple spots on the palms and soles.", "Infective endocarditis", "Edward Janeway, a New York physician, in 1899."],
  ["Osler nodes", "sign", "Painful, tender lumps on the finger and toe pads.", "Infective endocarditis", "William Osler, a Canadian physician, in 1909. Painful Osler, painless Janeway."],
  ["Roth spots", "sign", "Retinal haemorrhages with pale centres.", "Classically infective endocarditis (also leukaemia and others)", "Moritz Roth, a Swiss pathologist, in 1872."],
  ["Corrigan’s pulse", "sign", "A pulse that slaps up and collapses away quickly (water-hammer pulse).", "Aortic regurgitation", "Dominic Corrigan, an Irish physician, in 1832."],
  ["De Musset’s sign", "sign", "The head bobs with each heartbeat.", "Severe aortic regurgitation", "Named after the French poet Alfred de Musset, whose head bobbed. He had syphilitic aortic disease."],
  ["Quincke’s sign", "sign", "Pressing lightly on a fingernail shows a visible pulse in the nail bed.", "Aortic regurgitation", "Heinrich Quincke, a German physician, in 1868. He also pioneered the lumbar puncture."],
  ["Kussmaul’s sign", "sign", "The jugular venous pressure rises on breathing in instead of falling.", "Constrictive pericarditis (or right heart failure)", "Adolf Kussmaul, a German physician, in 1873."],
  ["Kussmaul breathing", "sign", "Deep, sighing, laboured breathing.", "Severe metabolic acidosis, classically diabetic ketoacidosis", "Adolf Kussmaul again, in 1874. Two eponyms, one man."],
  ["Ewart’s sign", "sign", "Dullness and bronchial breathing below the left shoulder blade.", "A large pericardial effusion pressing on the left lung", "William Ewart, a London physician, in 1896."],
  ["Levine’s sign", "sign", "A clenched fist held over the chest to describe the pain.", "Ischaemic heart pain (angina)", "Samuel Levine, a Boston cardiologist, in the 1950s."],
  ["Pemberton’s sign", "sign", "Raising both arms above the head makes the face flush and swell.", "A goitre extending behind the sternum, blocking the neck veins", "Hugh Pemberton, a Liverpool physician, in 1946."],
  ["Apgar score", "test", "Colour, heart rate, reflexes, muscle tone and breathing, each scored 0 to 2 at 1 and 5 minutes.", "How a newborn is coping straight after birth", "Virginia Apgar, an American anaesthetist, in 1952. Her name became the acronym later."],
  ["Beck’s triad", "triad", "Low blood pressure, raised jugular venous pressure and muffled heart sounds.", "Cardiac tamponade", "Claude Beck, an American cardiac surgeon, in 1935."],
  ["Charcot’s triad", "triad", "Fever (often with rigors), right upper abdominal pain and jaundice.", "Ascending cholangitis", "Jean-Martin Charcot, a French neurologist, in 1877. He has more eponyms than almost anyone."],
  ["Reynolds’ pentad", "triad", "Fever, right upper abdominal pain and jaundice, plus confusion and low blood pressure.", "Severe (suppurative) cholangitis", "Benedict Reynolds and Everett Dargan in 1959."],
  ["Cushing’s triad", "triad", "High blood pressure, a slow heart rate and irregular breathing.", "Raised pressure inside the skull, a late and dangerous sign", "Harvey Cushing, the American founder of modern neurosurgery, in 1901."],
  ["Virchow’s triad", "triad", "Slow blood flow, damage to the vessel wall and blood that clots too easily.", "The causes of thrombosis", "Credited to Rudolf Virchow, though the triad was put together by others after his 1856 work."],
  ["Whipple’s triad", "triad", "Hypoglycaemia symptoms, a measured low glucose and relief when glucose is given.", "Confirms true hypoglycaemia, e.g. insulinoma", "Allen Whipple, an American pancreatic surgeon, in 1938."],
  ["Hakim’s triad", "triad", "Gait problems, urinary incontinence and memory decline: ‘wet, wacky and wobbly’.", "Normal pressure hydrocephalus", "Salomón Hakim, a Colombian neurosurgeon, in 1965. A treatable cause of dementia."],
  ["Saint’s triad", "triad", "Gallstones, hiatus hernia and diverticular disease together.", "An association to remember when one is found", "Charles Saint, a South African surgeon, in the 1940s."],
  ["Horner’s syndrome", "syndrome", "Droopy eyelid, small pupil and less sweating on one side of the face.", "Damage to the sympathetic nerve supply, e.g. a lung apex tumour or carotid dissection", "Johann Friedrich Horner, a Swiss ophthalmologist, in 1869."],
  ["Meigs’ syndrome", "syndrome", "A benign ovarian tumour with ascites and a pleural effusion.", "Fluid that resolves once the ovarian tumour is removed", "Joe Vincent Meigs, an American gynaecologist, in 1937."],
  ["Kartagener syndrome", "syndrome", "Situs inversus, chronic sinusitis and bronchiectasis.", "Primary ciliary dyskinesia (cilia that don’t beat properly)", "Manes Kartagener, a Swiss physician, in 1933."],
  ["Trousseau’s syndrome", "syndrome", "Clots that keep appearing in different veins (migratory thrombophlebitis).", "A hidden cancer, classically pancreatic", "Armand Trousseau in 1865. He later recognised it in himself and died of stomach cancer."],
  ["Ortolani test", "test", "Gently abducting a newborn’s flexed hip produces a clunk as the hip slips back into the socket.", "Developmental dysplasia of the hip (a dislocated hip that can be reduced)", "Marino Ortolani, an Italian paediatrician, in 1937."],
  ["Barlow test", "test", "Pushing a newborn’s flexed, adducted hip backwards makes it slip out of the socket.", "Developmental dysplasia of the hip (a hip that can be dislocated)", "Thomas Geoffrey Barlow, an English orthopaedic surgeon, in 1962."],
  ["Galeazzi sign", "sign", "Child lying with hips and knees bent: one knee sits lower than the other.", "A shortened thigh, classically from a dislocated hip", "Riccardo Galeazzi, an Italian orthopaedic surgeon."],
  ["Thomas test", "test", "Lying flat, the patient hugs one knee to the chest and the other thigh lifts off the bed.", "A fixed flexion deformity of the hip", "Hugh Owen Thomas, a Welsh bonesetter’s son and surgeon, also famous for the Thomas splint."],
  ["Patrick’s (FABER) test", "test", "The ankle rests on the opposite knee and the bent knee is pushed down: pain in the groin or buttock.", "Hip joint or sacroiliac joint problems", "Hugh Talbot Patrick, a Chicago neurologist. FABER = flexion, abduction, external rotation."],
  ["Lasègue’s sign", "sign", "Lifting the straight leg reproduces shooting pain down the back of the leg.", "Lumbar nerve root irritation (sciatica)", "Charles Lasègue, a French physician, credited by his student; today usually called the straight leg raise."],
  ["Spurling’s test", "test", "Tilting and pressing down on the extended head reproduces pain running down the arm.", "Cervical nerve root compression (radiculopathy)", "Roy Glenwood Spurling and William Scoville, American neurosurgeons, in 1944."],
  ["Neer’s test", "test", "Lifting the straight, inwardly rotated arm forwards causes pain at the front of the shoulder.", "Subacromial impingement (rotator cuff pain)", "Charles Neer, an American shoulder surgeon, in 1972."],
  ["Hawkins–Kennedy test", "test", "With the shoulder and elbow bent to 90°, rotating the arm inwards causes shoulder pain.", "Subacromial impingement", "Richard Hawkins and J. C. Kennedy, Canadian orthopaedic surgeons, in 1980."],
  ["Jobe’s test", "test", "Arms out at 30° forwards, thumbs down (‘empty can’): weakness or pain pressing them down.", "Supraspinatus tendon tear or tendinopathy", "Frank Jobe, the American surgeon who also invented ‘Tommy John’ elbow surgery."],
  ["Speed’s test", "test", "Resisting forward lift of the straight, palm-up arm causes pain at the front of the shoulder.", "Long head of biceps tendon problems", "J. Spencer Speed, an American orthopaedic surgeon."],
  ["Yergason’s test", "test", "Resisted turning of the forearm palm-up with the elbow bent causes pain at the front of the shoulder.", "Biceps tendon inflammation or instability in its groove", "Robert Yergason, an American surgeon, in 1931."],
  ["Apley grind test", "test", "Patient lies face down, knee bent to 90°: pressing down and twisting the foot causes knee pain.", "Meniscal tear", "Alan Apley, a British orthopaedic surgeon and author of a famous textbook, in 1947."],
  ["Ober’s test", "test", "Lying on one side, the upper leg stays up in the air instead of dropping when released.", "A tight iliotibial band", "Frank Ober, a Boston orthopaedic surgeon, in 1936."],
  ["Durkan’s test", "test", "Pressing directly over the carpal tunnel for 30 seconds brings on tingling in the fingers.", "Carpal tunnel syndrome", "John Durkan, an American hand surgeon, in 1991."],
  ["Watson’s test", "test", "Pushing on the scaphoid while moving the wrist sideways causes a painful clunk.", "Scapholunate ligament instability", "H. Kirk Watson, an American hand surgeon."],
  ["Wartenberg’s sign", "sign", "The little finger drifts away from the ring finger and can’t be pulled back in.", "Ulnar nerve palsy", "Robert Wartenberg, a German-born neurologist who worked in San Francisco."],
  ["Heberden’s nodes", "sign", "Hard, bony lumps on the joints closest to the fingertips.", "Osteoarthritis of the finger end joints", "William Heberden, an English physician, in the 1700s. He also gave the first clear account of angina."],
  ["Bouchard’s nodes", "sign", "Hard, bony lumps on the middle joints of the fingers.", "Osteoarthritis of the middle finger joints", "Charles-Joseph Bouchard, a French pathologist and student of Charcot."],
  ["Kanavel’s signs", "sign", "A finger held slightly bent, swollen like a sausage, tender along the tendon and very painful to straighten.", "Flexor tendon sheath infection (a surgical emergency)", "Allen Kanavel, a Chicago surgeon, in 1912."],
  ["Matles test", "test", "Lying face down with knees bent, one foot falls into a neutral position instead of pointing slightly down.", "Achilles tendon rupture", "Arthur Matles, an American orthopaedic surgeon, in 1975."],
  ["Mulder’s click", "sign", "Squeezing the forefoot while pressing between the toes produces a painful click.", "Morton’s neuroma", "Jacob Mulder, a Dutch surgeon, in 1951."],
  ["Kleiger test", "test", "Turning the foot outwards with the knee bent causes pain above or inside the ankle.", "High ankle (syndesmosis) or deltoid ligament injury", "Barnard Kleiger, an American orthopaedic surgeon, in 1956."],
  ["Hoover’s sign", "sign", "A ‘paralysed’ leg pushes down firmly when the patient lifts the good leg against resistance.", "Functional (non-organic) leg weakness", "Charles Franklin Hoover, an American physician, in 1908."],
  ["Waddell’s signs", "sign", "Back pain with widespread tenderness, pain on light skin touch, and findings that change when the patient is distracted.", "A strong non-physical (psychosocial) part to back pain", "Gordon Waddell, a Scottish orthopaedic surgeon, in 1980. Not a test for faking."],
  ["Gaenslen’s test", "test", "One hip is fully bent while the other leg hangs off the bed: pain in the low back or buttock.", "Sacroiliac joint problems", "Frederick Gaenslen, an American orthopaedic surgeon."],
  ["Adson’s test", "test", "Turning the head and breathing in while the arm is held out makes the wrist pulse fade.", "Thoracic outlet syndrome", "Alfred Adson, an American neurosurgeon at the Mayo Clinic."],
  ["Schober’s test", "test", "Two marks on the lower back barely move apart when the patient bends forward.", "Reduced lumbar movement, e.g. ankylosing spondylitis", "Paul Schober, a German physician, in 1937."],
  ["Argyll Robertson pupil", "sign", "Small, irregular pupils that react to near focus but not to light.", "Neurosyphilis", "Douglas Argyll Robertson, a Scottish eye surgeon, in 1869."],
  ["Marcus Gunn pupil", "sign", "Swinging a torch between the eyes: one pupil gets bigger when the light moves onto it.", "Optic nerve disease on that side (relative afferent pupillary defect)", "Robert Marcus Gunn, a Scottish ophthalmologist."],
  ["Holmes–Adie pupil", "sign", "One large pupil that reacts very slowly, often with weak knee and ankle jerks.", "Adie tonic pupil (usually harmless)", "Gordon Holmes and William Adie, an Australian-born neurologist in London, in 1931 and 1932."],
  ["Uhthoff’s phenomenon", "sign", "Vision or other symptoms worsen in a hot shower or with exercise, then settle.", "Multiple sclerosis (heat slows damaged nerves)", "Wilhelm Uhthoff, a German ophthalmologist, in 1890."],
  ["Bell’s phenomenon", "sign", "The eyeball rolls upwards when the patient tries, but fails, to close one eye.", "Facial nerve palsy, e.g. Bell’s palsy", "Charles Bell, a Scottish surgeon and anatomist, in the early 1800s."],
  ["Brown-Séquard syndrome", "syndrome", "Weakness and loss of position sense on one side, loss of pain and temperature on the other.", "Damage to one half of the spinal cord", "Charles-Édouard Brown-Séquard, a Mauritian-born physiologist, in 1850."],
  ["Wernicke’s triad", "triad", "Confusion, unsteady walking and abnormal eye movements, often in heavy drinkers.", "Thiamine (vitamin B1) deficiency: Wernicke’s encephalopathy", "Carl Wernicke, a German neurologist, in 1881. Only a minority have all three, so treat on suspicion."],
  ["Korsakoff syndrome", "syndrome", "Severe loss of new memory, filled in with made-up stories (confabulation).", "Chronic thiamine deficiency, often after Wernicke’s", "Sergei Korsakoff, a Russian psychiatrist, in the 1880s."],
  ["Gerstmann syndrome", "syndrome", "Can’t name fingers, write, do sums or tell left from right.", "A lesion in the dominant parietal lobe (angular gyrus)", "Josef Gerstmann, an Austrian neurologist, in 1924."],
  ["Anton syndrome", "syndrome", "A patient who is blind insists they can see, and describes things that aren’t there.", "Cortical blindness from damage to both occipital lobes", "Gabriel Anton, an Austrian neuropsychiatrist, in 1899."],
  ["Charles Bonnet syndrome", "syndrome", "Vivid, silent visual hallucinations (people, patterns) in someone with poor sight, who knows they aren’t real.", "Vision loss, not mental illness", "Charles Bonnet, a Swiss naturalist, in 1760, describing his grandfather."],
  ["Klüver–Bucy syndrome", "syndrome", "Putting objects in the mouth, loss of fear, and disinhibited behaviour.", "Damage to both temporal lobes (amygdala)", "Heinrich Klüver and Paul Bucy, from experiments in monkeys, in 1937."],
  ["Parinaud syndrome", "syndrome", "Can’t look up, pupils react to near focus but not light, eyes jerk back on looking up.", "A lesion of the dorsal midbrain, e.g. a pineal tumour", "Henri Parinaud, a French ophthalmologist."],
  ["Weber syndrome", "syndrome", "A droopy eye that points down and out on one side, weakness of the opposite arm and leg.", "A midbrain stroke", "Hermann Weber, a German-born London physician, in 1863."],
  ["Wallenberg syndrome", "syndrome", "Sudden vertigo, hoarseness, trouble swallowing, a droopy eyelid and loss of pain on one side of the face and the other side of the body.", "Lateral medullary stroke (vertebral or PICA artery)", "Adolf Wallenberg, a German neurologist, in 1895."],
  ["Guillain–Barré syndrome", "syndrome", "Weakness rising from the feet over days, with lost reflexes, often after a gut or chest infection.", "Acute inflammatory nerve damage (polyneuropathy)", "Georges Guillain, Jean-Alexandre Barré and André Strohl, French army doctors, in 1916."],
  ["Miller Fisher triad", "triad", "Double vision from weak eye muscles, unsteadiness and absent reflexes.", "A variant of Guillain–Barré syndrome (anti-GQ1b antibodies)", "C. Miller Fisher, a Canadian neurologist, in 1956."],
  ["Lambert–Eaton syndrome", "syndrome", "Weak hips and shoulders that improve briefly with effort, dry mouth and absent reflexes.", "Antibodies to calcium channels, often from small cell lung cancer", "Edward Lambert and Lee Eaton, at the Mayo Clinic, in 1956."],
  ["Tullio phenomenon", "sign", "Loud noises cause dizziness and the world seems to move.", "Superior semicircular canal dehiscence (a thin spot in the inner ear bone)", "Pietro Tullio, an Italian biologist, from experiments in pigeons, in 1929."],
  ["Dix–Hallpike test", "test", "Lying the patient back quickly with the head turned brings on brief vertigo and a twisting eye flicker.", "Benign paroxysmal positional vertigo (BPPV)", "Margaret Dix and Charles Hallpike, British otologists, in 1952."],
  ["Rinne test", "test", "A tuning fork is heard better on the bone behind the ear than in front of it.", "Conductive hearing loss in that ear", "Heinrich Rinne, a German otologist, in 1855."],
  ["Weber test", "test", "A tuning fork on the middle of the forehead sounds louder in one ear.", "Hearing loss: conductive on the loud side or sensorineural on the quiet side", "Ernst Heinrich Weber, a German physiologist."],
  ["Jendrassik manoeuvre", "test", "The patient hooks their fingers together and pulls hard while the knee is tapped.", "A way to bring out reflexes that seem absent", "Ernő Jendrassik, a Hungarian neurologist, in 1883."],
  ["Myerson’s sign", "sign", "Tapping between the eyebrows keeps causing blinks instead of stopping after a few taps.", "Parkinson’s disease", "Abraham Myerson, an American neurologist. Also called the glabellar tap sign."],
  ["Todd’s paresis", "sign", "Weakness of one side for hours after a seizure, then full recovery.", "A temporary post-seizure weakness, not a stroke", "Robert Bentley Todd, an Irish physician in London, in 1849."],
  ["Cheyne–Stokes breathing", "sign", "Breathing that grows deeper, then shallower, then stops for a while, in cycles.", "Heart failure, stroke, high altitude or opioids", "John Cheyne, a Scottish doctor, and William Stokes, an Irish doctor, in the early 1800s."],
  ["Biot’s breathing", "sign", "Irregular clusters of quick breaths separated by pauses, with no pattern.", "Damage to the breathing centre in the brainstem", "Camille Biot, a French physician, in 1876."],
  ["Tourette syndrome", "syndrome", "Several motor tics and at least one vocal tic, starting in childhood, for more than a year.", "A tic disorder (swearing is actually uncommon)", "Georges Gilles de la Tourette, a French neurologist, in 1885."],
  ["Lazarus sign", "sign", "Arms rise and cross on the chest in a patient who is brain dead.", "A spinal reflex, which can happen after brain death", "Named after Lazarus of the Bible. Described by Alan Ropper in 1984."],
  ["Austin Flint murmur", "sign", "A low rumble in diastole at the apex, with no mitral stenosis.", "Severe aortic regurgitation", "Austin Flint, an American physician, in 1862."],
  ["Graham Steell murmur", "sign", "A soft early diastolic murmur at the upper left chest in pulmonary hypertension.", "Pulmonary regurgitation", "Graham Steell, an English physician, in 1888."],
  ["Carey Coombs murmur", "sign", "A short mid-diastolic murmur at the apex in a child with a recent sore throat and fever.", "Acute rheumatic fever (inflamed mitral valve)", "Carey Coombs, an English cardiologist, in 1924."],
  ["Duroziez’s sign", "sign", "Pressing a stethoscope on the femoral artery gives a to-and-fro murmur.", "Aortic regurgitation", "Paul Louis Duroziez, a French physician, in 1861."],
  ["Traube’s sign", "sign", "A loud ‘pistol shot’ sound heard over the femoral artery with each beat.", "Aortic regurgitation (pistol-shot femorals)", "Ludwig Traube, a German physician."],
  ["Müller’s sign", "sign", "The uvula pulses with each heartbeat.", "Aortic regurgitation (uvula)", "Friedrich von Müller, a German physician, in 1889."],
  ["Hill’s sign", "sign", "Blood pressure in the leg is far higher than in the arm (over 60 mmHg).", "Severe aortic regurgitation", "Leonard Hill, an English physiologist, in 1909."],
  ["Ortner’s syndrome", "syndrome", "A hoarse voice in someone with a very large left atrium.", "Recurrent laryngeal nerve compression, classically from mitral stenosis", "Norbert Ortner, an Austrian physician, in 1897."],
  ["Dressler syndrome", "syndrome", "Fever and sharp chest pain from pericarditis weeks after a heart attack.", "Immune-mediated pericarditis after heart injury", "William Dressler, an American cardiologist, in 1956. Rare since modern heart attack care."],
  ["Eisenmenger syndrome", "syndrome", "A blue tinge and finger clubbing in an adult with a hole in the heart since birth.", "A shunt that has reversed because of pulmonary hypertension", "Victor Eisenmenger, an Austrian physician, in 1897."],
  ["Wolff–Parkinson–White pattern", "sign", "ECG: short PR interval and a slurred upstroke to the QRS (delta wave).", "An extra electrical pathway between atria and ventricles", "Louis Wolff, John Parkinson and Paul Dudley White, in 1930."],
  ["Brugada pattern", "sign", "ECG: coved ST elevation in V1 and V2 in a young person who fainted.", "An inherited sodium channel disease with a risk of sudden death", "Pedro and Josep Brugada, Spanish cardiologist brothers, in 1992."],
  ["Osborn wave", "sign", "ECG: a hump at the end of the QRS complex.", "Hypothermia", "John Osborn, an American researcher, in 1953."],
  ["Wellens’ sign", "sign", "ECG: deep or biphasic T waves in V2 and V3 after chest pain has settled.", "A critical narrowing of the left anterior descending artery", "Hein Wellens, a Dutch cardiologist, in 1982."],
  ["de Winter T waves", "sign", "ECG: upsloping ST depression with tall, symmetrical T waves across the chest leads.", "A blocked left anterior descending artery (STEMI equivalent)", "Robbert de Winter, a Dutch cardiologist, in 2008."],
  ["Sgarbossa criteria", "test", "Rules for spotting a heart attack on an ECG that already shows left bundle branch block.", "Acute myocardial infarction hidden by LBBB", "Elena Sgarbossa, an Argentinian-born cardiologist, in 1996."],
  ["Kerley B lines", "sign", "Chest X-ray: short horizontal white lines at the lung edges near the bases.", "Fluid in the lung tissue, e.g. heart failure", "Peter Kerley, an Irish radiologist."],
  ["Hampton’s hump", "sign", "Chest X-ray: a wedge-shaped shadow against the pleura.", "Pulmonary infarction from a pulmonary embolism", "Aubrey Otis Hampton, an American radiologist, in 1940."],
  ["Westermark sign", "sign", "Chest X-ray: a patch of lung looks unusually dark, with fewer vessels.", "Pulmonary embolism (reduced blood flow)", "Nils Westermark, a Swedish radiologist, in 1938."],
  ["Buerger’s test", "test", "The raised leg turns white, then dark red when hung over the edge of the bed.", "Severe peripheral arterial disease", "Leo Buerger, an Austrian-born New York surgeon."],
  ["Raynaud’s phenomenon", "sign", "Fingers turn white, then blue, then red in the cold.", "Spasm of small arteries (vasospasm)", "Maurice Raynaud, a French physician, in 1862."],
  ["Hamman’s sign", "sign", "A crunching sound in time with the heartbeat.", "Air in the mediastinum (pneumomediastinum)", "Louis Hamman, a Johns Hopkins physician, in 1939."],
  ["Stokes–Adams attacks", "sign", "Sudden collapse with pallor, then flushing on waking, without warning.", "Intermittent complete heart block", "Robert Adams and William Stokes, Irish physicians, in the 1800s."],
  ["Friedreich’s sign", "sign", "The neck veins collapse sharply and deeply in early diastole.", "Constrictive pericarditis", "Nikolaus Friedreich, a German neurologist and physician, who also gave his name to an ataxia."],
  ["Rivero-Carvallo sign", "sign", "A murmur at the lower left sternum that gets louder on breathing in.", "Tricuspid regurgitation", "José Manuel Rivero Carvallo, a Mexican cardiologist, in 1946."],
  ["Leriche syndrome", "triad", "Buttock pain on walking, weak or absent leg pulses, and erectile dysfunction.", "Blockage of the end of the aorta and iliac arteries", "René Leriche, a French surgeon, in 1940."],
  ["Takayasu arteritis", "syndrome", "A young woman with absent arm pulses and different blood pressures in each arm.", "Large-vessel vasculitis of the aorta and its branches", "Mikito Takayasu, a Japanese ophthalmologist, in 1908. Also called ‘pulseless disease’."],
  ["Osler’s manoeuvre", "test", "The radial artery can still be felt as a firm tube after the cuff is pumped above systolic pressure.", "Stiff arteries falsely raising blood pressure readings (pseudohypertension)", "William Osler, the Canadian physician often called the father of modern medicine."],
  ["Light’s criteria", "test", "Comparing protein and LDH in pleural fluid and blood.", "Whether a pleural effusion is an exudate or a transudate", "Richard Light, an American lung specialist, in 1972."],
  ["Boas’ sign", "sign", "An area of extra-sensitive skin below the right shoulder blade.", "Acute cholecystitis", "Ismar Boas, a German gastroenterologist."],
  ["Dance’s sign", "sign", "The right lower abdomen feels empty, with a sausage-shaped mass higher up.", "Intussusception", "Jean Baptiste Hippolyte Dance, a French physician."],
  ["Fox’s sign", "sign", "Bruising below the inguinal ligament at the top of the thigh.", "Bleeding behind the abdomen, e.g. severe pancreatitis", "George Henry Fox, an American dermatologist."],
  ["Mallory–Weiss tear", "syndrome", "Fresh blood vomited after a bout of forceful retching.", "A tear in the lining where the oesophagus meets the stomach", "Kenneth Mallory and Soma Weiss, Boston doctors, in 1929."],
  ["Boerhaave syndrome", "syndrome", "Severe chest pain after violent vomiting, with air under the skin of the neck.", "Full-thickness rupture of the oesophagus", "Herman Boerhaave, a Dutch physician, in 1724, after a Dutch admiral’s fatal feast."],
  ["Plummer–Vinson syndrome", "syndrome", "Trouble swallowing solids, a web in the upper oesophagus and iron deficiency.", "Oesophageal web with iron deficiency anaemia", "Henry Plummer and Porter Vinson, at the Mayo Clinic."],
  ["Zollinger–Ellison syndrome", "syndrome", "Many stubborn stomach ulcers, often in odd places, with diarrhoea.", "A gastrin-secreting tumour (gastrinoma)", "Robert Zollinger and Edwin Ellison, American surgeons, in 1955."],
  ["Budd–Chiari syndrome", "syndrome", "Abdominal pain, a big tender liver and fast-building ascites.", "Blockage of the hepatic veins", "George Budd, an English physician, and Hans Chiari, an Austrian pathologist."],
  ["Rigler’s sign", "sign", "X-ray: both the inside and outside walls of the bowel can be seen.", "Free air in the abdomen (pneumoperitoneum)", "Leo Rigler, an American radiologist, in 1941."],
  ["Chilaiditi sign", "sign", "X-ray: a loop of bowel sits between the liver and the right diaphragm.", "A harmless look-alike of free air under the diaphragm", "Demetrius Chilaiditi, a Greek radiologist working in Vienna, in 1910."],
  ["Kayser–Fleischer rings", "sign", "A golden-brown ring at the edge of the cornea.", "Copper build-up in Wilson disease", "Bernhard Kayser and Bruno Fleischer, German ophthalmologists, in the early 1900s."],
  ["Mirizzi syndrome", "syndrome", "Jaundice from a gallstone stuck in the gallbladder neck, pressing on the bile duct.", "External compression of the common hepatic duct by a gallstone", "Pablo Mirizzi, an Argentinian surgeon, in 1948."],
  ["Bouveret syndrome", "syndrome", "Vomiting from a large gallstone that has passed into the duodenum.", "Gastric outlet obstruction by a gallstone", "Léon Bouveret, a French physician, in 1896."],
  ["Rigler’s triad", "triad", "X-ray: air in the bile ducts, small bowel obstruction and a stone in an odd place.", "Gallstone ileus", "Leo Rigler, an American radiologist, in 1941."],
  ["Ogilvie syndrome", "syndrome", "A hugely swollen colon with no blockage, usually in someone very unwell in hospital.", "Acute colonic pseudo-obstruction", "William Heneage Ogilvie, a British surgeon, in 1948."],
  ["Alport syndrome", "syndrome", "Blood in the urine, hearing loss and eye changes, running in the family.", "A faulty type IV collagen gene", "Cecil Alport, a South African-born physician, in 1927."],
  ["Goodpasture syndrome", "syndrome", "Coughing blood and rapid kidney failure together.", "Antibodies against the basement membrane of lungs and kidneys (anti-GBM)", "Ernest Goodpasture, an American pathologist, in 1919, during the flu pandemic."],
  ["Fanconi syndrome", "syndrome", "Glucose, amino acids, phosphate and bicarbonate all leak into the urine.", "Failure of the proximal kidney tubule", "Guido Fanconi, a Swiss paediatrician."],
  ["Cushing’s syndrome", "syndrome", "Weight gain around the middle, rounded face, purple stretch marks and thin skin.", "Too much cortisol", "Harvey Cushing, an American neurosurgeon, in 1912."],
  ["Conn syndrome", "syndrome", "High blood pressure with low potassium.", "Primary hyperaldosteronism", "Jerome Conn, an American endocrinologist, in 1955."],
  ["Sheehan syndrome", "syndrome", "Can’t breastfeed and periods don’t return after a big bleed at birth.", "Pituitary damage from blood loss after childbirth", "Harold Sheehan, an English pathologist, in 1937."],
  ["Kallmann syndrome", "syndrome", "Delayed puberty and no sense of smell.", "Gonadotrophin-releasing hormone deficiency", "Franz Josef Kallmann, a German-American geneticist, in 1944."],
  ["Klinefelter syndrome", "syndrome", "A tall man with small, firm testes and infertility.", "An extra X chromosome (47,XXY)", "Harry Klinefelter, an American endocrinologist, in 1942."],
  ["Turner syndrome", "syndrome", "A short girl with a webbed neck who doesn’t go through puberty.", "A missing X chromosome (45,X)", "Henry Turner, an American endocrinologist, in 1938."],
  ["Nelson syndrome", "syndrome", "Darkening skin and a growing pituitary tumour after both adrenal glands were removed.", "Growth of an ACTH-producing pituitary tumour", "Don Nelson, an American physician, in 1958."],
  ["Waterhouse–Friderichsen syndrome", "syndrome", "A spreading purple rash and shock in a feverish child.", "Adrenal bleeding in overwhelming sepsis, classically meningococcal", "Rupert Waterhouse, an English physician, and Carl Friderichsen, a Danish paediatrician."],
  ["von Graefe’s sign", "sign", "The upper eyelid lags behind when looking down.", "Thyroid eye disease (lid lag)", "Albrecht von Graefe, a German ophthalmologist, in 1864."],
  ["Dalrymple’s sign", "sign", "The upper eyelid is pulled up, showing white above the iris.", "Thyroid eye disease (lid retraction)", "John Dalrymple, a British ophthalmologist."],
  ["Pel–Ebstein fever", "sign", "Fevers that come and go in cycles of one to two weeks.", "Hodgkin lymphoma", "Pieter Pel, a Dutch physician, and Wilhelm Ebstein, a German physician, in 1887."],
  ["Bence Jones protein", "test", "Urine contains free immunoglobulin light chains.", "Multiple myeloma", "Henry Bence Jones, an English physician, in 1847."],
  ["Auer rods", "sign", "Blood film: thin red needle shapes inside immature white cells.", "Acute myeloid leukaemia", "John Auer, an American physiologist, in 1906."],
  ["Howell–Jolly bodies", "sign", "Blood film: small dark dots inside red cells.", "No working spleen", "William Howell, an American physiologist, and Justin Jolly, a French histologist."],
  ["Heinz bodies", "sign", "Blood film with a special stain: clumps of damaged haemoglobin inside red cells.", "Oxidative damage to red cells, e.g. G6PD deficiency", "Robert Heinz, a German pathologist, in 1890."],
  ["Reed–Sternberg cells", "sign", "Biopsy: large cells with two nuclei like owl’s eyes.", "Hodgkin lymphoma (on biopsy)", "Dorothy Reed, an American pathologist, and Carl Sternberg, an Austrian pathologist, around 1900."],
  ["Coombs test", "test", "Antibodies or complement found stuck to the patient’s red cells.", "Immune (autoimmune or alloimmune) haemolysis", "Robin Coombs, a British immunologist, in 1945."],
  ["Evans syndrome", "syndrome", "Immune destruction of red cells and platelets at the same time.", "Autoimmune haemolysis with immune thrombocytopenia", "Robert Evans, an American physician, in 1951."],
  ["Sjögren’s syndrome", "syndrome", "Gritty dry eyes and a dry mouth, sometimes with swollen salivary glands.", "Autoimmune attack on tear and saliva glands", "Henrik Sjögren, a Swedish ophthalmologist, in 1933."],
  ["Schirmer test", "test", "A paper strip under the lower eyelid wets less than 5 mm in 5 minutes.", "Low tear production, e.g. Sjögren’s syndrome", "Otto Schirmer, a German ophthalmologist, in 1903."],
  ["Felty syndrome", "triad", "Rheumatoid arthritis with a big spleen and a low neutrophil count.", "A severe form of rheumatoid arthritis", "Augustus Felty, an American physician, in 1924."],
  ["Löfgren syndrome", "triad", "Red tender lumps on the shins, swollen ankles and big glands in both lung roots.", "Acute sarcoidosis (usually settles by itself)", "Sven Löfgren, a Swedish physician, in 1946."],
  ["Behçet’s triad", "triad", "Recurrent mouth ulcers, genital ulcers and red painful eyes.", "Behçet disease (a vasculitis)", "Hulusi Behçet, a Turkish dermatologist, in 1937."],
  ["Gottron’s papules", "sign", "Raised purple-red bumps over the knuckles.", "Dermatomyositis", "Heinrich Gottron, a German dermatologist."],
  ["Reiter’s triad", "triad", "Arthritis, conjunctivitis and urethritis after a gut or sexual infection.", "Reactive arthritis", "Hans Reiter, 1916. The name was dropped because of his Nazi war crimes."],
  ["Wegener’s granulomatosis", "syndrome", "Bloody nasal crusting, lung nodules and kidney inflammation.", "Granulomatosis with polyangiitis (ANCA vasculitis)", "Friedrich Wegener, 1936. Renamed because of his links to the Nazi party."],
  ["Churg–Strauss syndrome", "syndrome", "Late-onset asthma, very high eosinophils and vasculitis.", "Eosinophilic granulomatosis with polyangiitis", "Jacob Churg and Lotte Strauss, New York pathologists, in 1951."],
  ["Asboe-Hansen sign", "sign", "Pressing on an intact blister makes it spread sideways.", "Pemphigus (fragile, superficial blisters)", "Gustav Asboe-Hansen, a Danish dermatologist."],
  ["Leser–Trélat sign", "sign", "A sudden crop of many seborrhoeic keratoses.", "A hidden internal cancer, often of the gut", "Edmund Leser, a German surgeon, and Ulysse Trélat, a French surgeon."],
  ["Hutchinson’s sign", "sign", "Shingles blisters on the tip of the nose.", "Shingles that may involve the eye", "Jonathan Hutchinson, an English surgeon, who named many signs."],
  ["Hutchinson’s triad", "triad", "Notched front teeth, cloudy corneas and deafness in a child.", "Congenital syphilis", "Jonathan Hutchinson, an English surgeon, in the 1860s."],
  ["Dennie–Morgan folds", "sign", "An extra crease below each lower eyelid.", "Atopic eczema", "Charles Dennie and David Morgan, American doctors."],
  ["Wickham’s striae", "sign", "Fine white lacy lines on shiny purple itchy bumps or inside the cheeks.", "Lichen planus", "Louis-Frédéric Wickham, a French dermatologist, in 1895."],
  ["Forchheimer spots", "sign", "Small red spots on the soft palate with a fine rash and swollen neck glands.", "Rubella", "Frederick Forchheimer, an American paediatrician."],
  ["Koplik spots", "sign", "Tiny white spots like grains of salt inside the cheeks, before the rash.", "Measles", "Henry Koplik, an American paediatrician, in 1896."],
  ["Pastia’s lines", "sign", "Red lines of rash in skin creases such as the elbows.", "Scarlet fever", "Constantin Chiariu Pastia, a Romanian physician."],
  ["Beau’s lines", "sign", "Horizontal grooves across all the nails.", "A past serious illness or chemotherapy that paused nail growth", "Joseph Honoré Simon Beau, a French physician, in 1846."],
  ["Muehrcke’s lines", "sign", "Paired white bands across the nails that don’t move as the nail grows.", "Low albumin", "Robert Muehrcke, an American physician, in 1956."],
  ["Terry’s nails", "sign", "Mostly white nails with a narrow pink-brown band at the tip.", "Liver cirrhosis", "Richard Terry, an English physician, in 1954."],
  ["Lindsay’s nails", "sign", "Half-and-half nails: white near the base, red-brown near the tip.", "Chronic kidney disease", "Peter Lindsay, in 1967."],
  ["Mees’ lines", "sign", "A single white band across every nail, growing out together.", "Arsenic or other heavy metal poisoning", "R. A. Mees, a Dutch physician, in 1919."],
  ["Crowe sign", "sign", "Freckles in the armpits.", "Neurofibromatosis type 1", "Frank Crowe, an American physician, in 1964."],
  ["Lisch nodules", "sign", "Small tan bumps on the iris.", "Neurofibromatosis type 1 (iris)", "Karl Lisch, an Austrian ophthalmologist, in 1937."],
  ["Schamroth’s window test", "test", "Placing matching fingernails back to back: the diamond-shaped gap is gone.", "Finger clubbing", "Leo Schamroth, a South African cardiologist, who tested it on himself, in 1976."],
  ["Faget sign", "sign", "High fever with a pulse that stays slow.", "Typhoid, yellow fever or Legionella (relative bradycardia)", "Jean Charles Faget, a French-born New Orleans physician, in 1859."],
  ["Jarisch–Herxheimer reaction", "sign", "Fever, chills and aches a few hours after the first antibiotic dose for syphilis.", "Release of toxins from dying spirochaetes", "Adolf Jarisch, an Austrian dermatologist, and Karl Herxheimer, a German dermatologist."],
  ["Lemierre syndrome", "syndrome", "A sore throat, then a swollen neck, high fevers and spots in the lungs.", "Septic clot in the jugular vein, usually Fusobacterium", "André Lemierre, a French physician, in 1936."],
  ["Fitz-Hugh–Curtis syndrome", "syndrome", "Right upper abdominal pain in a young woman with pelvic infection.", "Perihepatitis from chlamydia or gonorrhoea", "Thomas Fitz-Hugh and Arthur Curtis, American doctors, in the 1930s."],
  ["Weil’s disease", "syndrome", "Jaundice, kidney failure and bleeding after contact with rat urine or floodwater.", "Severe leptospirosis", "Adolf Weil, a German physician, in 1886."],
  ["Fournier’s gangrene", "syndrome", "Rapidly spreading painful skin death of the scrotum and perineum.", "Necrotising fasciitis of the perineum", "Jean Alfred Fournier, a French dermatologist, in 1883."],
  ["Pancoast syndrome", "syndrome", "Shoulder pain, a droopy eyelid with a small pupil and a weak, wasted hand.", "A tumour at the top of the lung", "Henry Pancoast, an American radiologist, in 1924."],
  ["Caplan syndrome", "syndrome", "Many lung nodules in a coal miner with rheumatoid arthritis.", "Rheumatoid nodules with dust exposure (pneumoconiosis)", "Anthony Caplan, a Welsh physician, in 1953."],
  ["Löffler syndrome", "syndrome", "Patchy lung shadows that move around, with high eosinophils.", "A reaction to worms passing through the lungs, or to drugs", "Wilhelm Löffler, a Swiss physician, in 1932."],
  ["Prehn’s sign", "sign", "Lifting the painful testis eases the pain.", "Epididymitis rather than torsion (not reliable)", "Douglas Prehn, an American urologist, in 1934."],
  ["Peyronie’s disease", "syndrome", "A bent, sometimes painful erection with a firm lump in the shaft.", "A fibrous plaque in the penis", "François de la Peyronie, surgeon to King Louis XV, in 1743."],
  ["Asherman syndrome", "syndrome", "Periods stop or become very light after a uterine scrape.", "Scarring inside the uterus", "Joseph Asherman, a Czech-born Israeli gynaecologist, in 1948."],
  ["Stein–Leventhal syndrome", "syndrome", "No periods, excess hair, obesity and big ovaries with many cysts.", "Polycystic ovary syndrome (the original name)", "Irving Stein and Michael Leventhal, Chicago gynaecologists, in 1935."],
  ["MRKH syndrome", "syndrome", "No periods in a teenager with normal breasts and pubic hair, but no uterus.", "Müllerian agenesis (absent uterus and upper vagina)", "Mayer, Rokitansky, Küster and Hauser, over more than a century."],
  ["Chadwick’s sign", "sign", "A bluish colour of the cervix and vagina.", "Early pregnancy", "James Read Chadwick, an American gynaecologist, in 1886."],
  ["Hegar’s sign", "sign", "The lower part of the uterus feels very soft on examination.", "Early pregnancy (soft lower uterus)", "Alfred Hegar, a German gynaecologist."],
  ["Naegele’s rule", "test", "Add one year, subtract three months and add seven days to the first day of the last period.", "Estimated due date", "Franz Naegele, a German obstetrician, in the early 1800s."],
  ["Bishop score", "test", "Scoring the cervix for dilatation, length, softness, position and the baby’s station.", "How likely an induction of labour is to work", "Edward Bishop, an American obstetrician, in 1964."],
  ["Moro reflex", "sign", "A startled baby flings the arms out, then brings them back in.", "A normal newborn reflex (asymmetry suggests nerve or bone injury)", "Ernst Moro, an Austrian paediatrician, in 1918."],
  ["Erb’s palsy", "sign", "After a difficult birth, one arm hangs with the palm facing backwards (‘waiter’s tip’).", "Upper brachial plexus injury (C5 and C6)", "Wilhelm Erb, a German neurologist, in 1874."],
  ["Klumpke’s palsy", "sign", "After a difficult birth, the hand is clawed and weak, sometimes with a droopy eyelid.", "Lower brachial plexus injury (C8 and T1)", "Augusta Déjerine-Klumpke, an American-born French neurologist, in 1885."],
  ["Down syndrome", "syndrome", "Upslanting eyes, a single palm crease, low muscle tone and heart defects.", "Trisomy 21", "John Langdon Down, an English physician, in 1866."],
  ["Edwards syndrome", "syndrome", "A baby with clenched fists and overlapping fingers, rocker-bottom feet and heart defects.", "Trisomy 18", "John Edwards, an English geneticist, in 1960."],
  ["Patau syndrome", "syndrome", "A baby with cleft lip, extra fingers and small eyes.", "Trisomy 13", "Klaus Patau, a German-American geneticist, in 1960."],
  ["Noonan syndrome", "syndrome", "Short stature, a webbed neck and pulmonary valve stenosis in a boy or girl.", "A RAS-pathway gene change, often PTPN11", "Jacqueline Noonan, an American paediatric cardiologist, in 1963."],
  ["Prader–Willi syndrome", "syndrome", "A floppy newborn who later becomes constantly hungry.", "Loss of the father’s copy of genes on chromosome 15", "Andrea Prader, Heinrich Willi and Alexis Labhart, Swiss doctors, in 1956."],
  ["Angelman syndrome", "syndrome", "A very happy child with seizures, jerky movements and little speech.", "Loss of the mother’s copy of UBE3A on chromosome 15", "Harry Angelman, an English paediatrician, in 1965."],
  ["Williams syndrome", "syndrome", "A very sociable child with elfin features, narrowing above the aortic valve and high calcium.", "A small deletion on chromosome 7 (7q11.23)", "J. C. P. Williams, a New Zealand cardiologist, in 1961."],
  ["DiGeorge syndrome", "syndrome", "Heart defects, low calcium, frequent infections and a cleft palate.", "A deletion on chromosome 22 (22q11.2)", "Angelo DiGeorge, an American paediatric endocrinologist, in 1965."],
  ["Reye syndrome", "syndrome", "Vomiting, confusion and liver failure after aspirin during a viral illness in a child.", "Acute liver failure with brain swelling linked to aspirin", "Douglas Reye, an Australian pathologist in Sydney, in 1963."],
  ["Hirschberg test", "test", "The torch reflection sits in a different spot on each cornea.", "A squint (strabismus)", "Julius Hirschberg, a German ophthalmologist, in 1886."],
  ["Amsler grid", "test", "Straight lines on a grid look wavy or have gaps to one eye.", "Macular disease, e.g. age-related macular degeneration", "Marc Amsler, a Swiss ophthalmologist, in 1947."],
  ["Ishihara test", "test", "Can’t see the number hidden in a circle of coloured dots.", "Red-green colour blindness", "Shinobu Ishihara, a Japanese ophthalmologist, in 1917."],
  ["Seidel test", "test", "Fluorescein on the eye shows a stream of fluid flowing from one spot.", "A leaking eye wound (perforated globe)", "Erich Seidel, a German ophthalmologist."],
  ["Frey syndrome", "syndrome", "Sweating and flushing over the cheek while eating, after parotid surgery.", "Misdirected nerve regrowth (gustatory sweating)", "Łucja Frey, a Polish neurologist, in 1923."],
  ["Ramsay Hunt syndrome", "syndrome", "Facial palsy with a painful blistering rash in the ear.", "Shingles of the facial nerve (geniculate ganglion)", "James Ramsay Hunt, an American neurologist, in 1907."],
  ["Ménière’s triad", "triad", "Attacks of vertigo with ringing in the ear and fluctuating hearing loss.", "Ménière’s disease (inner ear fluid build-up)", "Prosper Ménière, a French physician, in 1861."],
  ["Gradenigo’s triad", "triad", "Ear discharge, pain behind the eye and double vision on looking to the side.", "Infection at the tip of the petrous temporal bone", "Giuseppe Gradenigo, an Italian otologist, in 1904."],
  ["Capgras syndrome", "syndrome", "Belief that a loved one has been replaced by an identical impostor.", "Delusional misidentification", "Joseph Capgras, a French psychiatrist, in 1923."],
  ["Cotard syndrome", "syndrome", "Belief that you are dead, rotting or don’t exist.", "Severe psychotic depression (nihilistic delusion)", "Jules Cotard, a French neurologist, in 1880."],
  ["Munchausen syndrome", "syndrome", "Repeatedly faking or causing illness to be cared for in hospital.", "Factitious disorder", "Named by Richard Asher in 1951 after Baron Münchhausen, a teller of tall tales."],
  ["Ganser syndrome", "syndrome", "Giving nearly-right answers on purpose: ‘2 plus 2 is 5’.", "A dissociative state (approximate answers)", "Sigbert Ganser, a German psychiatrist, in 1898, from prisoners awaiting trial."],
  ["de Clérambault syndrome", "syndrome", "A fixed belief that a famous or higher-status person is secretly in love with them.", "Erotomania", "Gaëtan Gatian de Clérambault, a French psychiatrist, in 1921."],
  ["Alice in Wonderland syndrome", "syndrome", "Things suddenly look far too big, too small or too far away.", "Migraine or Epstein–Barr virus, usually", "John Todd, an English psychiatrist, in 1955. Lewis Carroll had migraines."],
  ["Pickwickian syndrome", "syndrome", "Very obese, sleepy all day and breathing too little.", "Obesity hypoventilation syndrome", "Named after Joe, the sleepy boy in Dickens’ The Pickwick Papers."],
  ["Asperger’s syndrome", "syndrome", "Social difficulties and intense interests without language delay.", "Now part of autism spectrum disorder", "Hans Asperger, 1944. Dropped from the DSM partly after his Nazi-era record came to light."]
];
